private static void TestAiBuildDiagnosticDormancy()
{
    Assert(!AiBuildDiagnostic.HasObserver, "AI diagnostic observer is absent before registration");
    Assert(AiBuildDiagnostic.BeginWoodAttempt(6) == 0,
        "AI diagnostic attempt is inert without an observer");
    Assert(!AiBuildDiagnostic.TryGetCurrentWoodAttempt(out long id, out int playerId) &&
        id == 0 && playerId == 0, "AI diagnostic attempt state is absent");
    Assert(!AiBuildDiagnostic.SchedulerReady && !AiBuildDiagnostic.RouteReady,
        "AI diagnostic native observation points are not installed without an observer");
    AiBuildDiagnostic.PublishNearbyPathEvidence("wood-nearby-path-before",
        6, 0UL, 69, 98, -1, -1);
    AiBuildDiagnostic.Publish("route-result", 6, 0);
}

private static bool CaptureSelectionState(int playerId, EngineInterface.PlayState state,
    out LocalSelectionSnapshot snapshot) =>
    CaptureSelectionState(playerId, () => state, out snapshot);

private static bool CaptureSelectionState(int playerId, Func<EngineInterface.PlayState> readState,
    out LocalSelectionSnapshot snapshot)
{
    MethodInfo capture = typeof(LocalSelectionAPI).GetMethod("TryCaptureState",
        BindingFlags.Static | BindingFlags.NonPublic);
    object[] args = { playerId, readState, null };
    bool success = (bool)capture.Invoke(null, args);
    snapshot = (LocalSelectionSnapshot)args[2];
    return success;
}

private static void TestPlayerPerspectivePolicy()
{
    int multiplayer = (int)SHCDESE.Interop.Enums.eGameTypeModes.GAMETYPE_MULTIPLAYER;
    Assert(PlayerPerspectiveAPI.ShouldOverrideLocalPlayerId(1, multiplayer, 1, -1),
        "Original spectators with a selected view must have no controlled player.");
    Assert(PlayerPerspectiveAPI.ShouldOverrideLocalPlayerId(8, multiplayer, 1, 0),
        "The last occupied spectator slot must be supported.");
    Assert(!PlayerPerspectiveAPI.ShouldOverrideLocalPlayerId(1, multiplayer, 1, 1),
        "Eliminated players retain their controlled identity.");
    Assert(!PlayerPerspectiveAPI.ShouldOverrideLocalPlayerId(0, multiplayer, 1, -1),
        "A cleared view must not override the Script Extender result.");
    Assert(!PlayerPerspectiveAPI.ShouldOverrideLocalPlayerId(1, multiplayer, 0, -1),
        "Non-spectator matches must keep the original result.");
    Assert(!PlayerPerspectiveAPI.ShouldOverrideLocalPlayerId(1,
        (int)SHCDESE.Interop.Enums.eGameTypeModes.GAMETYPE_MAP, 1, -1),
        "Other game modes must keep the original result.");
}

